// Extrai dados do payload Uazapi e mapeia para whatsapp_messages
const body = $input.first().json.body;

// Extrai timestamp e converte para ISO string
const messageTimestamp = new Date(body.message.messageTimestamp);

// Extrai telefone do sender
const senderPhone = body.message.sender_pn.replace('@s.whatsapp.net', '').replace('@lid', '');
const contactPhone = body.chat.wa_isGroup ? null : senderPhone;

// Define direção baseado em fromMe
const direction = body.message.fromMe ? 'out' : 'in';

return [{
  whatsapp_owner: body.owner,
  chat_type: body.chat.wa_isGroup ? 'group' : 'private',
  chat_id: body.chat.wa_chatid,
  chat_name: body.chat.name,
  contact_phone: contactPhone,
  sender_phone: senderPhone,
  sender_name: body.message.senderName,
  recipient_phone: body.owner,
  direction: direction,
  message_type: body.message.type,
  message: body.message.text || '',
  caption: body.message.type !== 'text' ? body.message.content : null,
  media_url: null,
  media_mime_type: null,
  transcription: null,
  message_id: body.message.messageid,
  reply_to_message_id: body.message.quoted || null,
  forwarded: false,
  reaction: body.message.reaction || null,
  reacted_to_message_id: null,
  status: body.message.status || 'received',
  message_created_at: messageTimestamp.toISOString(),
  metadata: JSON.stringify({
    instanceName: body.instanceName,
    baseUrl: body.BaseUrl,
    source: body.message.source,
    wasApi: body.message.wasSentByApi,
    uazapiToken: body.token
  })
}];
